function Icon({ name, ...props }: { name: IconName } & SVGProps<SVGSVGElement>) { if (name === "spark") return null; return <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" {...props}>{iconPaths[name]}</svg>; }

function GoogleMark() { return <svg className="google-mark" aria-hidden="true" viewBox="0 0 24 24"><path fill="#4285F4" d="M21.8 12.2c0-.7-.1-1.5-.2-2.2H12v4.2h5.5a4.7 4.7 0 0 1-2 3.1V20h3.3c1.9-1.8 3-4.4 3-7.8Z"/><path fill="#34A853" d="M12 22c2.7 0 5-.9 6.7-2.3l-3.3-2.6c-.9.6-2.1 1-3.4 1a5.9 5.9 0 0 1-5.5-4.1H3.1v2.7A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.5 14a6 6 0 0 1 0-3.9V7.4H3.1a10 10 0 0 0 0 9.3L6.5 14Z"/><path fill="#EA4335" d="M12 6a5.4 5.4 0 0 1 3.8 1.5l2.9-2.8A9.7 9.7 0 0 0 12 2a10 10 0 0 0-8.9 5.4l3.4 2.7A5.9 5.9 0 0 1 12 6Z"/></svg>; }

function Login({ user }: { user: User | null }) {
  const navigate = useNavigate(); const [error, setError] = useState(""); const [signingIn, setSigningIn] = useState(false);
  if (user) return <Navigate to="/workspaces" replace />;
  function authErrorMessage(caught: unknown) { if (!(caught instanceof FirebaseError)) return "Google sign-in failed. Please try again."; const messages: Record<string, string> = { "auth/popup-closed-by-user": "Google sign-in was closed before completion.", "auth/cancelled-popup-request": "The previous Google sign-in attempt was cancelled.", "auth/popup-blocked": "Your browser blocked the Google sign-in popup. Allow popups and try again.", "auth/account-exists-with-different-credential": "This email already uses another sign-in method. Sign in with your existing method first.", "auth/network-request-failed": "Google sign-in could not reach Firebase. Check your connection and try again." }; return messages[caught.code] ?? "Google sign-in failed. Please try again."; }
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(""); setSigningIn(true); const form = new FormData(event.currentTarget); try { await signInWithEmailAndPassword(firebaseAuth, String(form.get("email")), String(form.get("password"))); navigate("/workspaces", { replace: true }); } catch { setError("Sign-in failed. Check your Averon account credentials."); } finally { setSigningIn(false); } }
  async function google() { setError(""); setSigningIn(true); try { await signInWithPopup(firebaseAuth, googleAuthProvider); navigate("/workspaces", { replace: true }); } catch (caught) { setError(authErrorMessage(caught)); } finally { setSigningIn(false); } }
  return <main className="login-screen"><section className="login-story"><Link className="login-brand" to="/login"><span className="brand-orb"><Icon name="spark" /></span><span><strong>Emmy</strong><small>Averon Remote Control</small></span></Link><div className="login-copy"><p className="eyebrow">Private intelligence</p><h1>Your business context.<br/><span>One calm interface.</span></h1><p>Access Emmy, your authorized workspaces, and the operational knowledge that keeps Averon businesses aligned.</p></div><div className="trust-note"><Icon name="shield"/><span><strong>Protected by Averon access controls</strong><small>Your existing workspace permissions remain authoritative.</small></span></div></section><section className="login-action"><div className="auth-card"><div className="auth-card-heading"><span className="mobile-brand-orb"><Icon name="spark"/></span><p className="eyebrow">Welcome back</p><h2>Sign in to Emmy</h2><p>Continue with your existing Averon account.</p></div><form onSubmit={submit}><label>Email address<input name="email" type="email" autoComplete="email" placeholder="you@company.com" required disabled={signingIn}/></label><label>Password<input name="password" type="password" autoComplete="current-password" placeholder="Enter your password" required disabled={signingIn}/></label><button className="primary-button" type="submit" disabled={signingIn}>{signingIn ? "Signing in…" : "Sign in securely"}<Icon name="arrow"/></button></form><div className="auth-divider"><span>or continue with</span></div><button className="google-button" type="button" onClick={() => void google()} disabled={signingIn}><GoogleMark/>Google</button>{error && <p className="error alert" role="alert">{error}</p>}<p className="auth-footnote"><Icon name="shield"/>Private access for authorized Averon users only.</p></div></section></main>;
}

function Protected({ user, children }: { user: User | null; children: ReactNode }) { const location = useLocation(); return user ? children : <Navigate to="/login" replace state={{ from: location.pathname }} />; }
function initials(session: SafeSession | null) { const value = session?.displayName || session?.email || "Averon User"; return value.split(/\s|@/).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase()).join(""); }
function pageLabel(pathname: string) { if (pathname.startsWith("/permissions")) return "Permission Control"; if (pathname.startsWith("/agents")) return "Agents"; if (pathname.startsWith("/runs")) return "Runs"; if (pathname.startsWith("/tasks")) return "Tasks"; if (pathname.startsWith("/automations")) return "Automations"; if (pathname.includes("business-os")) return "Business OS"; if (pathname.startsWith("/chat")) return "Private chat"; if (pathname.startsWith("/diagnostics")) return "Diagnostics"; if (pathname.startsWith("/notifications")) return "Notifications"; if (pathname.startsWith("/settings")) return "Settings"; return "Workspaces"; }

const navigation = [{ to: "/workspaces", label: "Workspaces", icon: "grid" }, { to: "/agents", label: "Agents", icon: "user" }, { to: "/permissions", label: "Permissions", icon: "shield" }, { to: "/runs", label: "Runs", icon: "pulse" }, { to: "/tasks", label: "Tasks", icon: "check" }, { to: "/automations", label: "Automations", icon: "briefcase" }, { to: "/notifications", label: "Notifications", icon: "bell" }] as const;
export function Shell({ children, session, selectedWorkspace, unreadCount, conversations, activeConversationId, onNewConversation, onSelectConversation, onDeleteConversation }: { children: ReactNode; session: SafeSession | null; selectedWorkspace?: WorkspaceSummary; unreadCount: number; conversations: EmmyConversation[]; activeConversationId: string; onNewConversation: () => Promise<void>; onSelectConversation: (item: EmmyConversation) => void; onDeleteConversation: (item: EmmyConversation) => Promise<void> }) {
  const location = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [chatsOpen, setChatsOpen] = useState(true);
  const [completedAway, setCompletedAway] = useState<Set<string>>(() => new Set());
  const [conversationMenu, setConversationMenu] = useState(""); const [deleteTarget, setDeleteTarget] = useState<EmmyConversation | null>(null); const [deleting, setDeleting] = useState(false); const [deleteError, setDeleteError] = useState("");
  const generationSnapshots = useSyncExternalStore(
    useCallback((notify) => conversationGenerations.subscribeRegistryChanges(notify), []),
    useCallback(() => conversationGenerations.snapshots(), []),
  );
  const accountRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    function close(event: MouseEvent) { if (!accountRef.current?.contains(event.target as Node)) setAccountOpen(false); if (!(event.target as Element).closest?.(".conversation-item")) setConversationMenu(""); }
    function keydown(event: KeyboardEvent) { if (event.key === "Escape") { setAccountOpen(false); setConversationMenu(""); setDeleteTarget(null); } }
    document.addEventListener("mousedown", close); document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("mousedown", close); document.removeEventListener("keydown", keydown); };
  }, []);
  const generatingConversationIds = new Set(generationSnapshots.filter((item) => item.status === "processing" || item.status === "streaming" || item.status === "applying" || item.status === "verifying" || item.status === "awaiting_persistence").map((item) => item.conversationId));
  useEffect(() => conversationGenerations.subscribeAll((snapshots) => { const completed = snapshots.filter((item) => item.status === "completed" && item.conversationId !== activeConversationId).map((item) => item.conversationId); if (completed.length) setCompletedAway((current) => new Set([...current, ...completed])); }), [activeConversationId]);
  const displayName = session?.displayName || session?.email?.split("@")[0] || "Authenticated user";
  return <div className="app-shell">
    <button className="mobile-menu" type="button" aria-label="Open navigation" aria-expanded={menuOpen} onClick={() => setMenuOpen(true)}><Icon name="menu"/></button>
    {menuOpen && <button className="nav-scrim" type="button" aria-label="Close navigation" onClick={() => setMenuOpen(false)}/>}
    <aside className={`sidebar ${menuOpen ? "open" : ""}`}>
      <div className="sidebar-head"><Link className="brand" to="/workspaces"><span className="brand-orb"><Icon name="spark"/></span><span><strong>Emmy</strong><small>Averon Remote Control</small></span></Link><button className="sidebar-close" type="button" aria-label="Close navigation" onClick={() => setMenuOpen(false)}><Icon name="x"/></button></div>
      <div className="sidebar-section"><p className="sidebar-label">Workspace</p>{selectedWorkspace ? <Link className="workspace-switcher" to="/workspaces"><WorkspaceIdentityMark workspace={selectedWorkspace.workspace}/><span><strong>{selectedWorkspace.workspace.name}</strong><small>{selectedWorkspace.role} access</small></span><Icon name="chevron"/></Link> : <div className="workspace-switcher empty-workspace"><span className="workspace-monogram"><Icon name="briefcase"/></span><span><strong>General mode</strong><small>No private workspace</small></span></div>}</div>
      <nav className="sidebar-scroll-region" aria-label="Primary navigation"><p className="sidebar-label">Control center</p>{navigation.slice(0,1).map((item) => <NavLink key={item.to} to={item.to} end className={({ isActive }) => isActive ? "active" : undefined}><Icon name={item.icon}/><span>{item.label}</span></NavLink>)}<div className="chat-nav"><div className="chat-nav-row"><NavLink to="/chat" className={({ isActive }) => isActive ? "active" : undefined}><Icon name="message"/><span>Chat with Emmy</span></NavLink><button type="button" className="new-chat-button" aria-label="New chat" onClick={() => void onNewConversation()}>+</button></div><button type="button" className="workspace-conversation-heading" aria-label={chatsOpen ? "Collapse workspace conversations" : "Expand workspace conversations"} aria-expanded={chatsOpen} onClick={() => setChatsOpen((open) => !open)}><span>{selectedWorkspace?.workspace.name || "General conversations"}</span><Icon name="chevron"/></button>{chatsOpen && <div className="conversation-nav">{conversations.map((item) => { const generating = generatingConversationIds.has(item.id); const completed = completedAway.has(item.id) && item.id !== activeConversationId; return <div className={`conversation-item ${item.id === activeConversationId ? "active" : ""}`} key={item.id}><button type="button" className="conversation-title" onClick={() => { setCompletedAway((current) => { const next = new Set(current); next.delete(item.id); return next; }); onSelectConversation(item); }} title={item.title}>{item.title}</button>{generating && <span className="generation-indicator" aria-label={`${item.title} is working`}/>} {!generating && completed && <span className="completion-indicator" aria-label={`${item.title} completed while away`}/>}<button type="button" className="conversation-more" aria-label={`Conversation options for ${item.title}`} aria-haspopup="menu" aria-expanded={conversationMenu === item.id} onClick={(event) => { event.stopPropagation(); setConversationMenu((open) => open === item.id ? "" : item.id); }}>⋯</button>{conversationMenu === item.id && <div className="conversation-menu" role="menu"><button type="button" role="menuitem" onClick={() => { setConversationMenu(""); setDeleteTarget(item); }}>Delete</button></div>}</div>; })}</div>}</div>{navigation.slice(1).map((item) => <NavLink key={item.to} to={item.to} className={({ isActive }) => isActive ? "active" : undefined}><Icon name={item.icon}/><span>{item.label}</span>{item.to === "/notifications" && unreadCount > 0 && <b className="nav-count">{unreadCount}</b>}</NavLink>)}{session?.isAdmin && <NavLink to="/diagnostics"><Icon name="pulse"/><span>Diagnostics</span></NavLink>}</nav>
      <div className="sidebar-footer" ref={accountRef}>{accountOpen && <div className="account-menu" role="menu"><Link role="menuitem" to="/settings" onClick={() => setAccountOpen(false)}><Icon name="settings"/>Settings</Link><button role="menuitem" type="button" onClick={() => void signOut(firebaseAuth)}><Icon name="arrow"/>Log out</button></div>}<button className="user-card" type="button" aria-haspopup="menu" aria-expanded={accountOpen} onClick={() => setAccountOpen((open) => !open)}><span className="avatar">{initials(session)}</span><span className="user-copy"><strong>{displayName}</strong><small>{session?.email || session?.role || "Averon account"}</small></span><Icon name="chevron"/></button></div>
    </aside>
      <div className="app-main"><header className="topbar"><div><span className="topbar-kicker">{selectedWorkspace?.business.name || "Averon Technologies"}</span><strong>{pageLabel(location.pathname)}</strong></div><div className="topbar-actions"><Link className="notification-link" to="/notifications" aria-label={unreadCount ? `${unreadCount} unread notifications` : "Notifications"}><Icon name="bell"/>{unreadCount > 0 && <span>{unreadCount}</span>}</Link></div></header><main className={`content ${location.pathname === "/chat" ? "chat-content" : ""}`}>{children}</main></div>{deleteTarget && <div className="dialog-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !deleting) { setDeleteTarget(null); setDeleteError(""); } }}><div className="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-conversation-title"><h2 id="delete-conversation-title">Delete this conversation?</h2><p>This cannot be undone.</p>{deleteError && <p className="error alert" role="alert">{deleteError}</p>}<div><button type="button" disabled={deleting} onClick={() => { setDeleteTarget(null); setDeleteError(""); }}>Cancel</button><button type="button" className="delete-button" disabled={deleting} onClick={async () => { setDeleting(true); setDeleteError(""); try { await onDeleteConversation(deleteTarget); setDeleteTarget(null); } catch { setDeleteError("This conversation could not be deleted. Please try again."); } finally { setDeleting(false); } }}>{deleting ? "Deleting…" : "Delete"}</button></div></div></div>}
  </div>;
}

function PageHeading({ eyebrow, title, body, action }: { eyebrow: string; title: string; body?: string; action?: ReactNode }) { return <header className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1>{body && <p>{body}</p>}</div>{action}</header>; }
function EmptyState({ icon = "spark", title, body, action }: { icon?: IconName; title: string; body: string; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon"><Icon name={icon}/></span><h2>{title}</h2><p>{body}</p>{action}</div>; }
function StatusBadge({ children, tone = "neutral" }: { children: ReactNode; tone?: "neutral" | "good" | "warning" | "bad" }) { return <span className={`badge ${tone}`}>{children}</span>; }

function Workspaces({ items, loading, error, selectedId, onSelect }: { items: WorkspaceSummary[]; loading: boolean; error: string; selectedId: string; onSelect: (item: WorkspaceSummary) => void }) {
  const navigate = useNavigate();
  function enterWorkspace(item: WorkspaceSummary) { onSelect(item); navigate("/chat"); }
  return <section>
    <PageHeading eyebrow="Business context" title="Your workspaces" body="Select the authorized business context Emmy should use." action={items.length ? <StatusBadge tone="good">{items.length} active {items.length === 1 ? "workspace" : "workspaces"}</StatusBadge> : undefined}/>
    {loading ? <div className="loading-grid" aria-label="Loading workspaces"><i/><i/><i/></div> : error ? <EmptyState icon="pulse" title="Unable to load workspaces" body={error}/> : items.length === 0 ? <EmptyState icon="briefcase" title="No workspace access yet" body="Your account has no active workspace memberships. Ask an Averon administrator to grant access to the workspace you need."/> : <div className="workspace-grid">{items.map((item) => { const selected = selectedId === item.workspace.id; return <article className={`workspace-card ${selected ? "selected" : ""}`} key={item.workspace.id}>
      <button className="workspace-select" type="button" onClick={() => enterWorkspace(item)} aria-label={`Open ${item.workspace.name} workspace`}>
        <span className="workspace-card-top"><WorkspaceIdentityMark workspace={item.workspace} className="workspace-logo"/>{selected ? <StatusBadge tone="good"><Icon name="check"/>Active</StatusBadge> : <StatusBadge>{item.workspace.status}</StatusBadge>}</span>
        <span className="workspace-card-body"><small>{item.business.name}</small><strong>{item.workspace.name}</strong><span>{item.role} access</span></span><span className="workspace-card-action">Open workspace<Icon name="arrow"/></span>
      </button><div className="workspace-card-links"><Link to="/chat" onClick={() => onSelect(item)}>Open workspace</Link><Link to={`/workspaces/${encodeURIComponent(item.workspace.id)}/business-os`} onClick={() => onSelect(item)}>Business OS</Link></div>
    </article>; })}</div>}
  </section>;
}

type ChatMessage = { id: string; role: "user" | "assistant"; content: string; createdAt?: unknown; citations?: BusinessOsCitation[]; action?: EmmyActionMetadata; presentation?: EmmyPresentationBlock[]; generationStatus?: "processing" | "completed" | "interrupted"; streaming?: boolean };
type SpeechRecognitionResultEvent = Event & { results: ArrayLike<{ 0: { transcript: string }; isFinal: boolean }> };
type SpeechRecognitionLike = { continuous: boolean; interimResults: boolean; lang: string; start(): void; stop(): void; abort(): void; onresult: ((event: SpeechRecognitionResultEvent) => void) | null; onerror: ((event: Event & { error?: string }) => void) | null; onend: (() => void) | null };
type SpeechRecognitionConstructor = new () => SpeechRecognitionLike;
function speechRecognitionConstructor() { const scope = window as typeof window & { SpeechRecognition?: SpeechRecognitionConstructor; webkitSpeechRecognition?: SpeechRecognitionConstructor }; return scope.SpeechRecognition ?? scope.webkitSpeechRecognition; }
function InlineText({ text }: { text: string }) { return <>{text.split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map((part, index) => part.startsWith("**") && part.endsWith("**") ? <strong key={index}>{part.slice(2, -2)}</strong> : <span key={index}>{part}</span>)}</>; }
function MessageBody({ content, streaming }: { content: string; streaming?: boolean }) { if (streaming) return <div className="message-body streaming-body" data-stream-content={content}><span className="streaming-text">{content}</span></div>; const blocks = messageBlocks(content); return <div className="message-body">{blocks.map((block, index) => { if (block.type === "heading") { const Tag = `h${block.level + 1}` as "h2" | "h3" | "h4"; return <Tag key={index}><InlineText text={block.text}/></Tag>; } if (block.type === "unordered-list") return <ul key={index}>{block.items.map((item, itemIndex) => <li key={itemIndex}><InlineText text={item}/></li>)}</ul>; if (block.type === "ordered-list") return <ol key={index}>{block.items.map((item, itemIndex) => <li key={itemIndex}><InlineText text={item}/></li>)}</ol>; return <p key={index}><InlineText text={block.text}/></p>; })}</div>; }
function actionState(action: EmmyActionMetadata) { if (action.warnings.some((warning) => /ALREADY_SATISFIED|no change/i.test(warning))) return "No change required"; if ("rollbackStatus" in action && action.rollbackStatus === "completed") return "Rolled back"; if (action.status === "failed") return "Failed"; if (action.status === "cancelled" || action.status === "rejected") return "Rejected"; if (action.status === "applying") return "Applying"; if (action.status === "verifying") return "Verifying"; if (action.status === "approval_required" || action.status === "proposed" || ("approvalStatus" in action && action.approvalStatus === "pending")) return "Awaiting approval"; if (action.status === "completed" && action.verificationStatus === "passed") return "Completed"; return action.status.replaceAll("_", " "); }
export function ActionSurface({ action, workspaceName, busy, onApprove, onReject }: { action: EmmyActionMetadata; workspaceName: string; busy: boolean; onApprove: (id: string) => void; onReject: (id: string) => void }) {
  const approval = actionState(action) === "Awaiting approval"; const source = action.actionType.startsWith("frontend.source.") || action.actionType.startsWith("backend.source."); const files = "targetFiles" in action ? action.targetFiles : action.actionType === "guardian.repair.plan" ? (action.expectedResources.length ? action.expectedResources : ["Exact affected resources not available"]) : [];
  const visibleState = actionState(action);
  return <section className={`operation-card operation-${actionState(action).toLowerCase().replaceAll(" ", "-")}`} data-action-id={action.actionId}><header><div><small>Authorized operation</small><strong>{action.actionType}</strong></div><StatusBadge tone={action.status === "failed" ? "bad" : approval ? "warning" : "good"}>{visibleState}</StatusBadge></header>{"summary" in action && action.summary && <p className="operation-summary">{action.summary}</p>}<dl><div><dt>Workspace</dt><dd>{workspaceName}</dd></div>{files.length > 0 && <div><dt>Target</dt><dd>{files.join(", ")}</dd></div>}{action.actionType === "guardian.repair.plan" && <><div><dt>Website</dt><dd>{action.websiteId}</dd></div><div><dt>Severity</dt><dd>{action.severity}</dd></div><div><dt>Evidence</dt><dd>{action.evidenceSummary}</dd></div><div><dt>Target</dt><dd>{action.target}</dd></div><div><dt>Specialists</dt><dd>{action.specialists.join(", ")}</dd></div><div><dt>Proposed repair</dt><dd>{action.proposedOutcome}</dd></div><div><dt>Verification plan</dt><dd>{action.verificationPlan.join(" ")}</dd></div><div><dt>Rollback</dt><dd>{action.rollbackPlan}</dd></div><div><dt>Deployment</dt><dd>Not performed</dd></div></>}{"risk" in action && <div><dt>Risk</dt><dd>{action.risk}</dd></div>}{"changedLines" in action && <div><dt>Changed lines</dt><dd>{action.changedLines}</dd></div>}{action.status === "failed" && action.warnings[0] && <div><dt>Error</dt><dd>{action.warnings[0]}</dd></div>}<div><dt>Verification</dt><dd>{action.verificationStatus}</dd></div>{source && <div><dt>Deployment</dt><dd>Not performed</dd></div>}</dl><details><summary>Operation details</summary><code>{action.actionId}</code>{"diff" in action && action.diff && <pre className="structured-code diff"><code>{action.diff}</code></pre>}{action.warnings.length > 0 && <p>{action.warnings.join(", ")}</p>}</details>{approval && <div className="operation-actions"><button type="button" disabled={busy} onClick={() => onReject(action.actionId)}>Reject</button><button type="button" className="approve-action" disabled={busy} onClick={() => onApprove(action.actionId)}>{busy ? "Processing…" : "Approve"}</button></div>}</section>;
}
function StructuredResponseSurfaces({ blocks }: { blocks: EmmyPresentationBlock[] }) { return <div className="structured-surfaces">{blocks.map((block, index) => block.type === "table" ? <div className="compact-table-wrap" key={index}><table><thead><tr>{block.columns.map((column) => <th key={column}>{column}</th>)}</tr></thead><tbody>{block.rows.map((row, rowIndex) => <tr key={rowIndex}>{block.columns.map((_, cellIndex) => <td key={cellIndex}>{row[cellIndex] ?? ""}</td>)}</tr>)}</tbody></table></div> : block.type === "file" ? <div className="file-result-card" key={index}><code>{block.path}</code><StatusBadge tone={block.status === "completed" ? "good" : "neutral"}>{block.status}</StatusBadge>{block.summary && <p>{block.summary}</p>}</div> : <pre className={`structured-code ${block.type}`} key={index}><code>{block.content}</code></pre>)}</div>; }
const workspacePrompts = ["Review the available Business OS", "Draft content from current context", "Analyze SEO opportunities", "Prepare structured documentation"];
const generalPrompts = ["What does Averon Technologies build?", "Which Averon service fits my project?", "How do I start a project inquiry?"];

export function PrivateEmmyChat({ workspace, hasWorkspaces, conversation, onConversationCreated, onConversationUpdated }: { workspace?: WorkspaceSummary; hasWorkspaces: boolean; conversation?: EmmyConversation; onConversationCreated: (item: EmmyConversation) => void; onConversationUpdated: () => Promise<void> }) {
  const messagesEnd = useRef<HTMLDivElement>(null);
  const chatPage = useRef<HTMLElement>(null);
  const followLatest = useRef(true);
  const composerRef = useRef<HTMLTextAreaElement>(null);
  const sendInFlight = useRef(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState("");
  const [localLifecycle, setLifecycle] = useState<"idle" | "sending" | "processing" | "streaming" | "completed" | "failed">("idle");
  const [error, setError] = useState("");
  const [showScrollToBottom, setShowScrollToBottom] = useState(false);
  const [contextStatus] = useState<"ready" | "empty" | "uninitialized" | null>(null);
  const [copiedMessageId, setCopiedMessageId] = useState(""); const [listening, setListening] = useState(false); const [voiceError, setVoiceError] = useState(""); const recognition = useRef<SpeechRecognitionLike | null>(null);
  const prompts = workspace ? workspacePrompts : generalPrompts;
  const contextName = workspace?.workspace.name || "General mode";

  const createdForSend = useRef("");
  const conversationId = conversation?.id;
  const transcriptScope = transcriptScopeKey(conversationId, workspace?.workspace.id);
  const subscribeGeneration = useCallback((notify: () => void) => conversationId ? conversationGenerations.subscribeChanges(conversationId, notify) : () => undefined, [conversationId]);
  const readGeneration = useCallback(() => conversationId ? conversationGenerations.snapshot(conversationId) : undefined, [conversationId]);
  const generationSnapshot = useSyncExternalStore(subscribeGeneration, readGeneration, readGeneration);
  const lifecycle = generationSnapshot ? generationSnapshot.status === "timed_out" || generationSnapshot.status === "cancelled" ? "failed" : generationSnapshot.status : localLifecycle;
  const sending = !["idle", "completed", "failed"].includes(lifecycle);
  const activity = assistantActivityPresentation(generationSnapshot, localLifecycle);
  const actionProgress = generationSnapshot?.actionState;
  const renderedMessages = actionProgress
    ? mergeStreamCompletion(messages, { id: actionProgress.assistantMessage.id, role: "assistant", content: actionProgress.assistantMessage.content, createdAt: new Date().toISOString(), action: actionProgress.action as EmmyActionMetadata, generationStatus: "completed" as const })
    : activity?.kind === "streaming"
    ? mergeStreamCompletion(messages, { id: `stream-${conversationId}`, role: "assistant", content: activity.content ?? "", createdAt: new Date().toISOString(), streaming: true })
    : mergePersistedTerminal(messages, generationSnapshot, (completion) => ({ id: completion.assistantMessage.id, role: "assistant", content: completion.assistantMessage.content, createdAt: new Date().toISOString(), citations: completion.assistantMessage.citations as BusinessOsCitation[] | undefined, action: completion.action as EmmyActionMetadata | undefined, generationStatus: "completed" as const }));
  const latestActionMessage = new Map(renderedMessages.filter((item) => item.action).map((item) => [item.action!.actionId, item.id]));
  const renderedContextStatus = generationSnapshot?.completion?.businessOsStatus ?? contextStatus;
  useEffect(() => { if (isActiveSendConversationActivation(createdForSend.current, conversationId)) { createdForSend.current = ""; return; } let active = true; Promise.resolve().then(() => { if (active) { setMessages([]); setError(""); setLifecycle(conversationId && conversationGenerations.isActive(conversationId) ? "processing" : "idle"); composerRef.current?.focus(); } if (!conversationId) return null; return averonApi.conversations.messages(conversationId); }).then((response) => { if (active && response) { const persisted = response.data.items.map((item: EmmyConversationMessage) => ({ id: item.id, role: item.role, content: item.content, createdAt: item.createdAt, citations: item.citations, action: item.action, presentation: item.presentation, generationStatus: item.generationStatus })); conversationGenerations.reconcilePersistedMessages(conversationId!, persisted); setMessages(mergePersistedTerminal(persisted, conversationGenerations.snapshot(conversationId!), (completion) => ({ id: completion.assistantMessage.id, role: "assistant", content: completion.assistantMessage.content, createdAt: new Date().toISOString(), citations: completion.assistantMessage.citations as BusinessOsCitation[] | undefined, action: completion.action as EmmyActionMetadata | undefined, presentation: undefined, generationStatus: "completed" as const }))); } }).catch(() => { if (active) setError("This conversation could not be loaded."); }); return () => { active = false; }; }, [transcriptScope, conversationId]);
  useEffect(() => { if (conversationId && conversationGenerations.isActive(conversationId)) void conversationGenerations.reconcileUntilTerminal(conversationId, async () => (await averonApi.conversations.messages(conversationId)).data.items); }, [conversationId, lifecycle]);
  useEffect(() => () => recognition.current?.abort(), []);
  function scrollToLatest(behavior: ScrollBehavior = "smooth") { const container = chatPage.current?.closest<HTMLElement>(".chat-content"); if (!container) return; followLatest.current = true; setShowScrollToBottom(false); container.scrollTo({ top: container.scrollHeight, behavior }); }
  useEffect(() => { const container = chatPage.current?.closest<HTMLElement>(".chat-content"); if (!container) return; const onScroll = () => { const nearBottom = isNearChatBottom(container.scrollTop, container.clientHeight, container.scrollHeight); followLatest.current = nearBottom; setShowScrollToBottom(!nearBottom); }; container.addEventListener("scroll", onScroll, { passive: true }); onScroll(); return () => container.removeEventListener("scroll", onScroll); }, []);
  useEffect(() => { if (followLatest.current) requestAnimationFrame(() => scrollToLatest(lifecycle === "streaming" ? "auto" : "smooth")); }, [messages, generationSnapshot, lifecycle]);

  async function sendMessage(raw: string) {
    const message = raw.trim();
    if (!message || sending || sendInFlight.current) return;
    sendInFlight.current = true;
    followLatest.current = true; setShowScrollToBottom(false);
    const settled = generationSnapshot?.status === "completed" ? generationSnapshot.completion : undefined;
    const settledMessage = settled ? { id: settled.assistantMessage.id, role: "assistant" as const, content: settled.assistantMessage.content, createdAt: new Date().toISOString(), citations: settled.assistantMessage.citations as BusinessOsCitation[] | undefined, action: settled.action as EmmyActionMetadata | undefined, generationStatus: "completed" as const } : undefined;
    const baselineMessageIds = [...messages.map((item) => item.id), ...(settledMessage ? [settledMessage.id] : [])];
    setMessages((current) => [...(settledMessage ? mergeStreamCompletion(current, settledMessage) : current), { id: `local-user-${Date.now()}`, role: "user", content: message, createdAt: new Date().toISOString() }]);
    setDraft(""); setError(""); setLifecycle("sending");
    try {
      let current = conversation; if (!current) { const created = await averonApi.conversations.create(workspace?.workspace.id ?? null); current = created.data; createdForSend.current = current.id; onConversationCreated(current); }
      if (!workspace) { const response = await averonApi.conversations.send(current.id, message); setMessages((items) => [...items, { id: response.data.assistantMessage.id, role: "assistant", content: response.data.assistantMessage.content, createdAt: new Date().toISOString(), citations: response.data.assistantMessage.citations, action: response.data.assistantMessage.action, generationStatus: "completed" }]); setLifecycle("completed"); refreshConversationList(onConversationUpdated); return; }
      setLifecycle("processing");
      const generation = conversationGenerations.start(current.id, message, (onEvent) => averonApi.conversations.stream(current.id, message, { onEvent: (event: EmmyStreamEvent) => onEvent(event) }), { knownPersistedMessageIds: baselineMessageIds });
      void conversationGenerations.reconcileUntilTerminal(current.id, async () => (await averonApi.conversations.messages(current.id)).data.items);
      await generation;
      refreshConversationList(onConversationUpdated);
    } catch (caught) {
      if (caught instanceof DOMException && caught.name === "AbortError") return;
      const code = caught instanceof AveronApiError ? caught.failure.error.code : "";
      setLifecycle("failed");
      setError(code === "PRIVATE_EMMY_RATE_LIMITED" || code === "EMMY_RATE_LIMITED" ? "Emmy is receiving too many requests. Please wait a moment." : code === "WORKSPACE_ACCESS_DENIED" || code === "WORKSPACE_PERMISSION_DENIED" ? "Your access to this workspace has changed. Select another workspace or continue in general mode." : "Emmy could not answer right now. Your message remains in this conversation.");
    } finally { sendInFlight.current = false; }
  }
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); void sendMessage(draft); }
  function approveAction(action: EmmyActionMetadata) { if (action.actionType === "guardian.repair.plan") { void sendMessage(`Approve Guardian repair plan ${action.actionId}.`); return; } const kind = action.actionType.startsWith("backend.source.") ? "backend" : "frontend"; void sendMessage(`Apply ${kind} source proposal ${action.actionId}.`); }
  function rejectAction(action: EmmyActionMetadata) { if (action.actionType === "guardian.repair.plan") { void sendMessage(`Reject Guardian repair plan ${action.actionId}.`); return; } const kind = action.actionType.startsWith("backend.source.") ? "backend" : "frontend"; void sendMessage(`Reject ${kind} source proposal ${action.actionId}.`); }

  function keyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); event.currentTarget.form?.requestSubmit(); }
  }

  async function copyMessage(item: ChatMessage) { try { await navigator.clipboard.writeText(item.content); setCopiedMessageId(item.id); window.setTimeout(() => setCopiedMessageId((current) => current === item.id ? "" : current), 1600); } catch { setError("This message could not be copied. Select the text and copy it manually."); } }
  function toggleVoice() { if (listening) { recognition.current?.stop(); return; } const Recognition = speechRecognitionConstructor(); if (!Recognition) { setVoiceError("Voice input is not supported by this browser. You can continue typing."); return; } setVoiceError(""); const next = new Recognition(); recognition.current = next; next.continuous = true; next.interimResults = true; next.lang = navigator.language || "en-US"; let finalTranscript = draft.trim(); next.onresult = (event) => { let interim = ""; for (let index = 0; index < event.results.length; index += 1) { const result = event.results[index]; if (result.isFinal) finalTranscript = `${finalTranscript} ${result[0].transcript}`.trim(); else interim += result[0].transcript; } setDraft(`${finalTranscript}${interim ? ` ${interim}` : ""}`.trim()); }; next.onerror = (event) => { if (event.error !== "aborted") setVoiceError(event.error === "not-allowed" ? "Microphone access was denied. Allow access in your browser settings to use voice input." : "Voice input stopped unexpectedly. You can continue typing."); setListening(false); }; next.onend = () => { setListening(false); recognition.current = null; }; setListening(true); next.start(); }

  return <section className="chat-page" ref={chatPage}>
    <div className="chat-context-bar"><StatusBadge tone={workspace ? "good" : "neutral"}><span className="status-dot"/>{workspace ? `${workspace.workspace.name} · ${workspace.role} access` : "General mode"}</StatusBadge>{workspace || hasWorkspaces ? <Link className="context-switch-link" to="/workspaces">{workspace ? "Change workspace" : "Select workspace"}</Link> : <span className="workspace-access-note">No private workspace access</span>}</div>
    {renderedContextStatus && renderedContextStatus !== "ready" && <div className="context-note"><Icon name="shield"/><span><strong>{renderedContextStatus === "empty" ? "Business OS has no active context" : "Business OS is not initialized"}</strong><small>{renderedContextStatus === "empty" ? "Emmy will clearly distinguish general guidance." : "General guidance will be labeled and no business facts will be invented."}</small></span></div>}
    <div className="chat-panel"><div className="messages" aria-live="polite">{renderedMessages.length === 0 && !activity ? <div className="chat-welcome"><h2>What would you like me to work on?</h2><div className="prompt-grid">{prompts.map((prompt) => <button type="button" key={prompt} onClick={() => { setDraft(prompt); composerRef.current?.focus(); }}><span>{prompt}</span><Icon name="arrow"/></button>)}</div></div> : renderedMessages.map((item) => { const timestamp = formatMessageTime(item.createdAt); return <article className={`message ${item.role} ${item.generationStatus === "interrupted" ? "interrupted" : ""}`} key={item.id}><div className="message-content"><header><strong>{item.role === "user" ? "You" : "Emmy"}</strong><span className="message-meta"><small>{item.generationStatus === "interrupted" ? "Response interrupted" : item.role === "assistant" ? workspace ? "Private AI" : "General mode" : contextName}</small>{timestamp && <time>{timestamp}</time>}<button type="button" className="message-copy" onClick={() => void copyMessage(item)} aria-label={`Copy ${item.role === "assistant" ? "Emmy response" : "message"}`}><Icon name={copiedMessageId === item.id ? "check" : "copy"}/>{copiedMessageId === item.id ? "Copied" : "Copy"}</button></span></header><MessageBody content={item.content} streaming={item.streaming}/>{item.presentation?.length ? <StructuredResponseSurfaces blocks={item.presentation}/> : null}{item.action && workspace && latestActionMessage.get(item.action.actionId) === item.id && <ActionSurface action={item.action} workspaceName={workspace.workspace.name} busy={sending} onApprove={() => approveAction(item.action!)} onReject={() => rejectAction(item.action!)}/>} {workspace && item.citations?.length ? <div className="citations"><span><Icon name="shield"/>Sources</span>{item.citations.map((citation) => <Link key={`${citation.sectionType}-${citation.citationId || "source"}`} to={`/workspaces/${encodeURIComponent(workspace.workspace.id)}/business-os`}>{citation.label}{citation.version ? ` · v${citation.version}` : ""}</Link>)}</div> : null}</div></article>; })}{activity?.kind === "working" && <article className="message assistant thinking"><div className="message-content"><header><strong>Emmy</strong><small>Emmy is working…</small></header><div className="thinking-dots"><i/><i/><i/></div></div></article>}{activity?.kind === "reconnecting" && <article className="message assistant thinking"><div className="message-content"><header><strong>Emmy</strong><small>Emmy is reconnecting…</small></header>{activity.content ? <MessageBody content={activity.content}/> : <div className="thinking-dots"><i/><i/><i/></div>}</div></article>}{activity?.kind === "terminal_failure" && <article className="message assistant interrupted"><div className="message-content"><header><strong>Emmy</strong><small>Response interrupted</small></header><MessageBody content={activity.content || "Emmy could not reconnect to this response. Please try again."}/></div></article>}<div ref={messagesEnd}/></div>{showScrollToBottom && <button type="button" className="scroll-to-bottom" aria-label="Scroll to latest message" onClick={() => scrollToLatest()}><Icon name="down"/></button>}{error && <p className="error alert" role="alert">{error}</p>}{voiceError && <p className="error alert" role="alert">{voiceError}</p>}<form className="composer" onSubmit={submit}><label className="sr-only" htmlFor="emmy-message">Message Emmy</label><textarea ref={composerRef} id="emmy-message" value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={keyDown} maxLength={2000} rows={2} placeholder={workspace ? `Ask Emmy about ${workspace.workspace.name}…` : "Ask Emmy about Averon…"} disabled={sending} required/><div className="composer-footer"><span><kbd>Enter</kbd> to send · <kbd>Shift</kbd> + <kbd>Enter</kbd> for new line</span><div className="composer-actions"><button type="button" className={`voice-button ${listening ? "listening" : ""}`} aria-label={listening ? "Stop voice input" : "Start voice input"} aria-pressed={listening} onClick={toggleVoice} disabled={sending}><Icon name={listening ? "x" : "microphone"}/>{listening ? "Stop" : "Voice"}</button><button type="submit" aria-label="Send message" disabled={sending || !draft.trim()}><Icon name="send"/>{sending ? "Working" : "Send"}</button></div></div></form><p className="chat-disclaimer"><Icon name="shield"/>{workspace ? "Business OS access remains limited to this authorized workspace." : "General mode cannot access Business OS or private workspace data."}</p></div>
  </section>;
}

const accessLabel = (value: string) => value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
export function AgentsCatalog({ catalog, permissions }: { catalog: AgentCatalogResponse; permissions?: WorkspacePermissionProjection }) {
  const [selected, setSelected] = useState<AgentCatalogItem | null>(null); const [tab, setTab] = useState<"overview" | "skills" | "permissions" | "certification">("overview");
  if (selected) { const effective = permissions?.agents.find((item) => item.id === selected.id); return <section className="agent-control"><button className="agent-back" type="button" onClick={() => setSelected(null)}>← All agents</button><PageHeading eyebrow="Specialist profile" title={selected.displayName} body={selected.displayRole} action={<StatusBadge tone={selected.readiness === "READY" ? "good" : "warning"}>{accessLabel(selected.readiness)}</StatusBadge>}/><div className="agent-detail"><nav className="agent-tabs" aria-label="Agent details">{(["overview", "skills", "permissions", "certification"] as const).map((item) => <button className={tab === item ? "active" : ""} type="button" key={item} onClick={() => setTab(item)}>{accessLabel(item)}</button>)}</nav>{tab === "overview" && <div className="agent-detail-grid"><AgentFact label="Internal ID" value={selected.id}/><AgentFact label="Internal role" value={selected.internalName}/><AgentFact label="Version" value={`v${selected.version}`}/><AgentFact label="Provider requirement" value={selected.providerRequirements.join(", ")}/><AgentFact label="Model capability" value={selected.modelCapabilities.join(", ")}/><AgentFact label="Business OS access" value={selected.businessOsAccess}/><AgentFact label="Schema" value={selected.schemaVersion}/><AgentFact label="Risk" value={selected.riskLevel}/></div>}{tab === "skills" && <div className="agent-skill-list">{selected.skills.map((skill) => <article key={skill.id}><strong>{skill.name}</strong><code>{skill.id}</code><p>{skill.description}</p><small>{skill.domain} · {skill.riskLevel} risk · {skill.requiredPermissions.join(", ")}{skill.requiredTools.length ? ` · tools: ${skill.requiredTools.join(", ")}` : " · no tools"}</small></article>)}</div>}{tab === "permissions" && (effective ? <PermissionSections agent={effective}/> : <div className="agent-permissions"><p>Effective permission data is unavailable.</p></div>)}{tab === "certification" && <div className="agent-detail-grid"><AgentFact label="Readiness" value={selected.readiness}/><AgentFact label="Last evaluation" value={selected.certification.lastEvalStatus}/><AgentFact label="Certification" value={selected.certification.certificationStatus}/><AgentFact label="Certified schema" value={selected.certification.certifiedSchemaVersion ?? "Not recorded"}/>{selected.readinessReasons.length > 0 && <AgentFact label="Readiness notes" value={selected.readinessReasons.join(" ")}/>}</div>}</div></section>; }
  return <section className="agent-control"><PageHeading eyebrow={catalog.workspace.name} title="Agent Control Center" body="Manage and inspect Emmy’s specialist team."/><div className="agent-summary"><AgentMetric value={catalog.summary.specialists} label="Specialists"/><AgentMetric value={catalog.summary.ready} label="Ready"/><AgentMetric value={catalog.summary.unavailable} label="Unavailable"/><AgentMetric value={catalog.summary.providerCapability} label="Configured capability"/></div><div className="agent-grid">{catalog.items.map((agent) => <button type="button" className="agent-card" key={agent.id} onClick={() => { setSelected(agent); setTab("overview"); }}><span className="agent-card-heading"><span className="agent-monogram">{agent.displayName.slice(0, 1)}</span><StatusBadge tone={agent.readiness === "READY" ? "good" : "warning"}>{accessLabel(agent.readiness)}</StatusBadge></span><strong>{agent.displayName}</strong><small>{agent.displayRole}</small><span className="agent-version">v{agent.version}</span><div className="agent-skill-chips">{agent.skills.slice(0, 3).map((skill) => <span key={skill.id}>{skill.name}</span>)}</div><p>Access: {agent.executionRights.map(accessLabel).join(" · ")}</p></button>)}</div></section>;
}
function AgentFact({ label, value }: { label: string; value: string }) { return <div className="agent-fact"><small>{label}</small><strong>{value}</strong></div>; }
function AgentMetric({ value, label }: { value: string | number; label: string }) { return <div><strong>{value}</strong><small>{label}</small></div>; }
const permissionTone = (state: PermissionControlState) => state === "automatic" ? "good" : state === "requires_approval" ? "warning" : "neutral";
function PermissionRow({ item }: { item: PermissionControlEntry }) { return <article className="permission-row"><span><strong>{item.label}</strong><small>{item.explanation}</small></span><StatusBadge tone={permissionTone(item.state)}>{item.state === "automatic" ? "✓ Automatic" : item.state === "requires_approval" ? "◷ Requires Approval" : "⊘ Blocked"}</StatusBadge></article>; }
function PermissionSections({ agent }: { agent: AgentPermissionProjection }) { return <div className="agent-permissions"><h2>Specialist authority</h2>{agent.specialistAuthority.map((item) => <PermissionRow key={item.id} item={item}/>)}<h2>Related server actions</h2>{agent.relatedActions.length ? agent.relatedActions.map((item) => <PermissionRow key={item.id} item={item}/>) : <p>No related Authorized Action is registered.</p>}<small>Specialists analyze and recommend. Server Authorized Actions enforce authorization, approval, and verification separately.</small></div>; }
export function AgentsView({ workspace }: { workspace?: WorkspaceSummary }) { const [result, setResult] = useState<{ workspaceId: string; catalog: AgentCatalogResponse | null; permissions: WorkspacePermissionProjection | null; error: string }>({ workspaceId: "", catalog: null, permissions: null, error: "" }); const workspaceId = workspace?.workspace.id ?? ""; useEffect(() => { let active = true; if (!workspaceId) return () => { active = false; }; Promise.all([averonApi.agents.list(workspaceId), averonApi.permissions.get(workspaceId)]).then(([catalog, permissions]) => { if (active) setResult({ workspaceId, catalog: catalog.data, permissions: permissions.data, error: "" }); }).catch(() => { if (active) setResult({ workspaceId, catalog: null, permissions: null, error: "The specialist catalog could not be loaded." }); }); return () => { active = false; }; }, [workspaceId]); if (!workspace) return <EmptyState icon="briefcase" title="Select a workspace" body="Choose an authorized workspace to inspect Emmy’s specialist team." action={<Link className="text-link" to="/workspaces">Choose workspace</Link>}/>; if (result.workspaceId === workspaceId && result.error) return <EmptyState icon="pulse" title="Agents unavailable" body={result.error}/>; if (result.workspaceId !== workspaceId || !result.catalog || !result.permissions) return <div className="loading-grid" aria-label="Loading agents"><i/><i/><i/></div>; return <AgentsCatalog catalog={result.catalog} permissions={result.permissions}/>; }

export function PermissionControl({ data }: { data: WorkspacePermissionProjection }) { return <section className="agent-control permission-control"><PageHeading eyebrow={data.workspace.name} title="Permission Control" body="Effective specialist and server-action authority for this workspace."/><div className="permission-flow"><span>Agent analyzes / recommends</span><b>→</b><span>Server Authorized Action</span><b>→</b><span>Authorization / approval / verification</span></div><h2>Authorized server actions</h2><div className="permission-list">{data.actions.map((item) => <PermissionRow key={item.id} item={item}/>)}</div><h2>Security boundaries</h2><div className="permission-list">{data.boundaries.map((item) => <PermissionRow key={item.id} item={item}/>)}</div></section>; }
export function PermissionsView({ workspace }: { workspace?: WorkspaceSummary }) { const [result, setResult] = useState<{ workspaceId: string; data: WorkspacePermissionProjection | null; error: string }>({ workspaceId: "", data: null, error: "" }); const workspaceId = workspace?.workspace.id ?? ""; useEffect(() => { let active = true; if (!workspaceId) return () => { active = false; }; averonApi.permissions.get(workspaceId).then((response) => { if (active) setResult({ workspaceId, data: response.data, error: "" }); }).catch(() => { if (active) setResult({ workspaceId, data: null, error: "Permission Control could not be loaded." }); }); return () => { active = false; }; }, [workspaceId]); if (!workspace) return <EmptyState icon="briefcase" title="Select a workspace" body="Choose an authorized workspace to inspect effective permissions."/>; if (result.workspaceId === workspaceId && result.error) return <EmptyState icon="shield" title="Permissions unavailable" body={result.error}/>; if (result.workspaceId !== workspaceId || !result.data) return <div className="loading-list" aria-label="Loading permissions"><i/><i/><i/></div>; return <PermissionControl data={result.data}/>; }

const runTone = (status: string) => status === "completed" || status === "no_change_required" ? "good" : status === "failed" || status === "rejected" || status === "rolled_back" ? "bad" : "warning";
const runDuration = (milliseconds: number) => milliseconds >= 1000 ? `${(milliseconds / 1000).toFixed(1)}s` : `${milliseconds}ms`;
export function RunsCatalog({ data, onOpen }: { data: WorkspaceRunsResponse; onOpen: (item: WorkspaceRunSummary) => void }) { const [filter, setFilter] = useState("all"); const [agent, setAgent] = useState(""); const [action, setAction] = useState(""); const statuses = ["all", "running", "awaiting_approval", "completed", "failed", "rejected"]; const agents = [...new Set(data.items.flatMap((item) => item.specialistIds))]; const actions = [...new Set(data.items.flatMap((item) => item.actionType ? [item.actionType] : []))]; const visible = data.items.filter((item) => (filter === "all" || filter === "running" ? filter === "all" || ["applying", "verifying"].includes(item.status) : item.status === filter) && (!agent || item.specialistIds.includes(agent)) && (!action || item.actionType === action)); return <section className="runs-page"><PageHeading eyebrow={data.workspace.name} title="Runs" body="See how Emmy and the specialist team execute work."/><div className="run-filters"><div>{statuses.map((status) => <button type="button" className={filter === status ? "active" : ""} key={status} onClick={() => setFilter(status)}>{accessLabel(status)}</button>)}</div><select aria-label="Filter runs by agent" value={agent} onChange={(event) => setAgent(event.target.value)}><option value="">All agents</option>{agents.map((id) => <option key={id}>{id}</option>)}</select><select aria-label="Filter runs by action" value={action} onChange={(event) => setAction(event.target.value)}><option value="">All actions</option>{actions.map((id) => <option key={id}>{id}</option>)}</select></div>{visible.length === 0 ? <EmptyState icon="pulse" title="No matching runs" body="No authoritative run records match these filters."/> : <div className="run-list">{visible.map((item) => <button type="button" key={item.operationId} onClick={() => onOpen(item)}><span><strong>{item.title}</strong><small>{item.specialists.map((specialist) => `${specialist.displayName} · ${specialist.displayRole}`).join(", ") || "Direct Emmy"}</small></span><StatusBadge tone={runTone(item.status)}>{accessLabel(item.status)}</StatusBadge><dl><div><dt>Duration</dt><dd>{runDuration(item.durationMs)}</dd></div><div><dt>Started</dt><dd>{new Date(item.startedAt).toLocaleString()}</dd></div><div><dt>Workspace</dt><dd>{item.workspace.name}</dd></div></dl></button>)}</div>}</section>; }
export function RunDetail({ run, onBack }: { run: WorkspaceRunDetail; onBack: () => void }) { return <section className="runs-page"><button className="agent-back" type="button" onClick={onBack}>← All runs</button><PageHeading eyebrow={run.workspace.name} title={run.title} body={`Operation ${run.operationId}`} action={<StatusBadge tone={runTone(run.status)}>{accessLabel(run.status)}</StatusBadge>}/><div className="run-detail-grid"><article className="run-trace"><h2>Execution</h2>{run.trace.map((stage, index) => <div key={`${stage.kind}-${index}`}><span className="run-trace-mark"><Icon name={stage.status === "failed" ? "x" : "check"}/></span><span><strong>{stage.label}</strong>{stage.status && <small>{accessLabel(stage.status)}</small>}{stage.occurredAt && <time>{new Date(stage.occurredAt).toLocaleString()}</time>}</span></div>)}</article><aside className="run-facts"><h2>Run facts</h2><AgentFact label="Validation" value={run.validationStatus}/><AgentFact label="Provider calls" value={String(run.providerCalls)}/><AgentFact label="Tokens" value={String(run.tokenUsage.totalTokens)}/><AgentFact label="Citations" value={String(run.grounding.citationCount)}/><AgentFact label="Critic" value={run.criticInvoked ? run.criticVerdict ?? "Invoked" : "Not required"}/>{run.taskId && <AgentFact label="Task" value={run.taskId}/>}{run.actionType && <AgentFact label="Action" value={run.actionType}/>}<AgentFact label="Errors" value={run.errorCodes.join(", ") || "None"}/></aside></div>{run.specialistDetails.length > 0 && <div className="run-specialists"><h2>Specialists</h2>{run.specialistDetails.map((item) => <article key={item.id}><header><div><strong>{item.displayName}</strong><small>{item.displayRole}</small></div><StatusBadge tone={item.status === "completed" ? "good" : "bad"}>{accessLabel(item.status)}</StatusBadge></header><dl><div><dt>Skills</dt><dd>{item.skills.join(", ") || "Not recorded"}</dd></div><div><dt>Provider calls</dt><dd>{item.providerCalls}</dd></div><div><dt>Validation</dt><dd>{item.validationStatus}</dd></div><div><dt>Duration</dt><dd>{runDuration(item.durationMs)}</dd></div></dl><Link to="/agents">View agent catalog</Link></article>)}</div>}</section>; }
export function RunsView({ workspace }: { workspace?: WorkspaceSummary }) { const [search, setSearch] = useSearchParams(); const requestedRun = search.get("run"); const [result, setResult] = useState<{ workspaceId: string; data: WorkspaceRunsResponse | null; error: string }>({ workspaceId: "", data: null, error: "" }); const [detail, setDetail] = useState<WorkspaceRunDetail | null>(null); const workspaceId = workspace?.workspace.id ?? ""; useEffect(() => { let active = true; if (!workspaceId) return () => { active = false; }; averonApi.runs.list(workspaceId).then((response) => { if (active) { setResult({ workspaceId, data: response.data, error: "" }); setDetail(null); if (requestedRun) void averonApi.runs.get(workspaceId, requestedRun).then((detailResponse) => { if (active) setDetail(detailResponse.data); }); } }).catch(() => { if (active) setResult({ workspaceId, data: null, error: "Runs could not be loaded." }); }); return () => { active = false; }; }, [workspaceId, requestedRun]); if (!workspace) return <EmptyState icon="briefcase" title="Select a workspace" body="Choose an authorized workspace to inspect its runs."/>; if (result.workspaceId === workspaceId && result.error) return <EmptyState icon="pulse" title="Runs unavailable" body={result.error}/>; if (result.workspaceId !== workspaceId || !result.data) return <div className="loading-list" aria-label="Loading runs"><i/><i/><i/></div>; if (detail) return <RunDetail run={detail} onBack={() => { setDetail(null); setSearch({}); }}/>; return <RunsCatalog data={result.data} onOpen={(item) => { setSearch({ run: item.operationId }); void averonApi.runs.get(workspaceId, item.operationId).then((response) => setDetail(response.data)); }}/>; }

export function DiagnosticsView() {
  const [items, setItems] = useState<AiDiagnostic[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  useEffect(() => { let active = true; averonApi.aiDiagnostics.list(50).then((response) => { if (active) setItems(response.data.items); }).catch(() => { if (active) setError("AI diagnostics could not be loaded."); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, []);
  return <section><PageHeading eyebrow="Authorized operations" title="AI diagnostics" body="Safe orchestration metadata for administrators. Prompts, messages, reasoning, and business content are never displayed." action={<StatusBadge><Icon name="shield"/>Admin only</StatusBadge>}/>{loading ? <div className="loading-list" aria-label="Loading diagnostics"><i/><i/><i/></div> : error ? <EmptyState icon="pulse" title="Diagnostics unavailable" body={error}/> : items.length === 0 ? <EmptyState icon="pulse" title="No diagnostics retained" body="This API instance has not retained an approved AI diagnostic yet."/> : <div className="diagnostics-list">{items.map((item) => { const status = diagnosticStatus(item); const tone = status === "completed" || status === "no change required" ? "good" : status === "failed" ? "bad" : "warning"; return <article key={item.requestId}><header><div><StatusBadge tone={tone}>{status}</StatusBadge><h2>{item.workspaceId}</h2><code>{item.requestId}</code></div><time dateTime={item.startedAt}>{new Date(item.startedAt).toLocaleString()}</time></header><div className="metric-row"><div><small>Duration</small><strong>{item.durationMs} ms</strong></div><div><small>Team size</small><strong>{item.selectedTeamSize ?? item.plan.taskCount}</strong></div><div><small>Provider calls</small><strong>{item.providerCalls}</strong></div><div><small>Tokens</small><strong>{item.tokenUsage.totalTokens || "—"}</strong></div><div><small>Citations</small><strong>{item.citations.length}</strong></div></div><dl>{item.operationAction && <div><dt>Action</dt><dd>{item.operationAction}</dd></div>}<div><dt>Validation</dt><dd>{item.attributionValidation || (item.tasks.every((task) => task.validationStatus === "valid") ? "valid" : "review required")}</dd></div><div><dt>Critic</dt><dd>{item.criticInvoked ? item.verifierStatus || "invoked" : "not required"}</dd></div><div><dt>Errors</dt><dd>{item.errorCodes.join(", ") || "None"}</dd></div><div><dt>Authorized team</dt><dd>{item.plan.agentIds.join(", ") || "Direct Emmy"}</dd></div></dl></article>; })}</div>}</section>;
}

function notificationDate(value: unknown) { if (typeof value === "string" || typeof value === "number") { const date = new Date(value); return Number.isNaN(date.valueOf()) ? "" : date.toLocaleString(); } if (value && typeof value === "object" && "_seconds" in value && typeof (value as { _seconds?: unknown })._seconds === "number") return new Date((value as { _seconds: number })._seconds * 1000).toLocaleString(); return ""; }
export function NotificationsView({ items, workspaces = [], loading, error, onStatus, onRead }: { items: WorkspaceNotification[]; workspaces?: WorkspaceSummary[]; loading: boolean; error: string; onStatus?: (id: string, status: WorkspaceNotificationStatus) => Promise<void>; onRead?: (id: string) => Promise<void> }) {
  const [workspaceFilter, setWorkspaceFilter] = useState(""); const [categoryFilter, setCategoryFilter] = useState(""); const [statusFilter, setStatusFilter] = useState("");
  const visible = items.filter((item) => (!workspaceFilter || item.workspaceId === workspaceFilter) && (!categoryFilter || item.category === categoryFilter) && (!statusFilter || item.status === statusFilter));
  const workspaceById = new Map(workspaces.map((item) => [item.workspace.id, item]));
  for (const item of items) if (!workspaceById.has(item.workspaceId)) { const identity = canonicalWorkspaceIdentity(item.workspaceId); if (identity) workspaceById.set(item.workspaceId, { workspace: { id: item.workspaceId, businessId: item.businessId ?? item.workspaceId, name: identity.name, slug: item.workspaceId, status: "active", logoUrl: identity.logoUrl }, business: { id: item.businessId ?? item.workspaceId, name: identity.name, slug: item.workspaceId, status: "active" }, role: "viewer", permissions: [] }); }
  return <section><PageHeading eyebrow="Workspace operations" title="Notifications" body="Authoritative operational activity, health reports, and action results across your authorized workspaces." action={items.some((item) => item.status === "unread") ? <StatusBadge tone="good">{items.filter((item) => item.status === "unread").length} unread</StatusBadge> : undefined}/>
    <div className="notification-filters" aria-label="Notification filters"><select aria-label="Filter by workspace" value={workspaceFilter} onChange={(event) => setWorkspaceFilter(event.target.value)}><option value="">All workspaces</option>{workspaces.map((item) => <option value={item.workspace.id} key={item.workspace.id}>{item.workspace.name}</option>)}</select><select aria-label="Filter by category" value={categoryFilter} onChange={(event) => setCategoryFilter(event.target.value)}><option value="">All categories</option>{[...new Set(items.map((item) => item.category))].map((category) => <option key={category}>{category.replaceAll("_", " ")}</option>)}</select><select aria-label="Filter by status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="">Read and unread</option><option value="unread">Unread</option><option value="read">Read</option></select></div>
    {loading ? <div className="loading-list"><i/><i/></div> : error ? <EmptyState icon="bell" title="Notifications unavailable" body={error}/> : visible.length === 0 ? <EmptyState icon="bell" title="You’re all caught up" body="No workspace operations match these filters."/> : <div className="notification-list">{visible.map((item) => { const workspace = workspaceById.get(item.workspaceId); return <article className={`${item.status} severity-${item.severity}`} key={item.notificationId}>{workspace ? <WorkspaceIdentityMark workspace={workspace.workspace} className="notification-icon"/> : <span className="notification-icon"><Icon name="bell"/></span>}<div><header><h2>{item.title}</h2><StatusBadge tone={item.severity === "critical" ? "bad" : item.severity === "warning" ? "warning" : item.severity === "success" ? "good" : "neutral"}>{item.severity}</StatusBadge></header><small>{workspace?.workspace.name ?? "Authorized workspace"} · {item.category.replaceAll("_", " ")}</small><p>{item.message}</p>{item.recommendation?.observed.map((line) => <p key={`observed-${line}`}><strong>Observed:</strong> {line}</p>)}{item.recommendation?.suggested.map((line) => <p key={`suggested-${line}`}><strong>Suggested:</strong> {line}</p>)}<time>{notificationDate(item.createdAt)}</time>{item.destination && <Link className="notification-destination" to={item.destination.path}>{item.destination.label}</Link>}</div><button type="button" onClick={() => void (onStatus ? onStatus(item.notificationId, item.status === "unread" ? "read" : "unread") : onRead?.(item.notificationId))}>Mark {item.status === "unread" ? "read" : "unread"}</button></article>; })}</div>}
  </section>;
}

function SettingsView({ session, apiOnline, selectedWorkspace }: { session: SafeSession | null; apiOnline: boolean | null; selectedWorkspace?: WorkspaceSummary }) {
  return <section><PageHeading eyebrow="Private app" title="Settings" body="Review the real account and connection context used by Emmy."/><div className="settings-grid"><article className="settings-card account-card"><div className="settings-title"><span className="settings-icon"><Icon name="user"/></span><div><small>Account</small><h2>Signed-in identity</h2></div></div><div className="account-summary"><span className="avatar large">{initials(session)}</span><div><strong>{session?.displayName || "Averon user"}</strong><span>{session?.email || "Email unavailable"}</span></div><StatusBadge>{session?.role || "user"}</StatusBadge></div><dl><div><dt>User ID</dt><dd>{session?.userId || "Unavailable"}</dd></div><div><dt>Administrative access</dt><dd>{session?.isAdmin ? "Enabled" : "Not enabled"}</dd></div></dl></article><article className="settings-card"><div className="settings-title"><span className="settings-icon"><Icon name="pulse"/></span><div><small>Connection</small><h2>System status</h2></div></div><div className={`connection-callout ${apiOnline ? "online" : ""}`}><span className="status-dot"/><div><strong>{apiOnline === null ? "Checking Averon API" : apiOnline ? "Connected" : "Offline"}</strong><p>{apiOnline ? "The private API is reachable and authenticated requests use your Firebase session." : "Emmy cannot reach the Averon API right now."}</p></div></div></article><article className="settings-card"><div className="settings-title"><span className="settings-icon"><Icon name="briefcase"/></span><div><small>Context</small><h2>Workspace preference</h2></div></div>{selectedWorkspace ? <div className="selected-setting"><span className="workspace-monogram">{selectedWorkspace.workspace.name.slice(0, 1)}</span><div><strong>{selectedWorkspace.workspace.name}</strong><span>{selectedWorkspace.business.name} · {selectedWorkspace.role}</span></div><Link to="/workspaces">Change</Link></div> : <EmptyState icon="briefcase" title="No workspace selected" body="Choose a workspace to establish Emmy’s private business context." action={<Link className="text-link" to="/workspaces">Choose workspace</Link>}/>}</article><article className="settings-card danger-card"><div className="settings-title"><span className="settings-icon"><Icon name="shield"/></span><div><small>Session</small><h2>Secure access</h2></div></div><p>Signing out ends this Firebase session on Emmy App. It does not alter your account or workspace memberships.</p><button className="secondary-button" type="button" onClick={() => void signOut(firebaseAuth)}>Sign out of Emmy<Icon name="arrow"/></button></article></div></section>;
}

export default function App() {
  const navigate = useNavigate();
  const [user, setUser] = useState<User | null>(firebaseAuth.currentUser); const [authReady, setAuthReady] = useState(false); const [apiOnline, setApiOnline] = useState<boolean | null>(null); const [session, setSession] = useState<SafeSession | null>(null); const [workspaces, setWorkspaces] = useState<WorkspaceSummary[]>([]); const [workspacesLoading, setWorkspacesLoading] = useState(false); const [workspaceError, setWorkspaceError] = useState(""); const [selectedWorkspaceId, setSelectedWorkspaceId] = useState(() => sessionStorage.getItem("averon:selected-workspace") || ""); const [conversations, setConversations] = useState<EmmyConversation[]>([]); const [activeConversationId, setActiveConversationId] = useState(() => sessionStorage.getItem("averon:active-conversation") || ""); const [notifications, setNotifications] = useState<WorkspaceNotification[]>([]); const [notificationsLoading, setNotificationsLoading] = useState(false); const [notificationsError, setNotificationsError] = useState("");
  useEffect(() => onAuthStateChanged(firebaseAuth, (next) => { setUser(next); if (!next) { setSession(null); setWorkspaces([]); setNotifications([]); } setAuthReady(true); }), []);
  useEffect(() => { averonApi.health().then(() => setApiOnline(true)).catch(() => setApiOnline(false)); }, []);
  useEffect(() => { if (!user) return; let active = true; averonApi.session().then((response) => { if (active) { setSession(response.data); setApiOnline(true); } }).catch(() => { if (active) setSession(null); }); return () => { active = false; }; }, [user]);
  useEffect(() => { if (!user) return; let active = true; Promise.resolve().then(() => { if (active) { setWorkspacesLoading(true); setWorkspaceError(""); } return averonApi.workspaces.list(); }).then((response) => { if (active) { setWorkspaces(response.data.items); const stored = sessionStorage.getItem("averon:selected-workspace") || ""; if (stored && !response.data.items.some((item) => item.workspace.id === stored)) { setSelectedWorkspaceId(""); sessionStorage.removeItem("averon:selected-workspace"); } } }).catch(() => { if (active) setWorkspaceError("Workspace access could not be retrieved from Averon API."); }).finally(() => { if (active) setWorkspacesLoading(false); }); return () => { active = false; }; }, [user]);
  useEffect(() => { if (!user) return; let active = true; Promise.resolve().then(() => { if (active) { setNotificationsLoading(true); setNotificationsError(""); } return averonApi.workspaceNotifications.list(); }).then((response) => { if (active) setNotifications(response.data.items); }).catch(() => { if (active) setNotificationsError("Workspace operations could not be loaded from Averon API."); }).finally(() => { if (active) setNotificationsLoading(false); }); return () => { active = false; }; }, [user]);
  const acceptConversations = useCallback((items: EmmyConversation[]) => { setConversations(items); setActiveConversationId((current) => { const retained = retainedConversationId(current, items.map((item) => item.id)); if (!retained) sessionStorage.removeItem("averon:active-conversation"); return retained; }); }, []);
  const loadConversationScope = useCallback(() => selectedWorkspaceId ? averonApi.conversations.listWorkspace(selectedWorkspaceId) : averonApi.conversations.listGeneral(), [selectedWorkspaceId]);
  const refreshConversations = useCallback(async () => { const response = await loadConversationScope(); acceptConversations(response.data.items); }, [acceptConversations, loadConversationScope]);
  useEffect(() => { if (!user) return; let active = true; loadConversationScope().then((response) => { if (active) acceptConversations(response.data.items); }).catch(() => { if (active) setConversations([]); }); return () => { active = false; }; }, [acceptConversations, loadConversationScope, user]);
  const selectWorkspace = (item: WorkspaceSummary) => { setSelectedWorkspaceId(item.workspace.id); setActiveConversationId(""); sessionStorage.setItem("averon:selected-workspace", item.workspace.id); sessionStorage.removeItem("averon:active-conversation"); }; const selectedWorkspace = workspaces.find((item) => item.workspace.id === selectedWorkspaceId); const unreadCount = notifications.filter((item) => item.status === "unread").length;
  async function setNotificationStatus(id: string, status: WorkspaceNotificationStatus) { try { const response = await averonApi.workspaceNotifications.setStatus(id, status); setNotifications((current) => current.map((item) => item.notificationId === id ? response.data : item)); } catch { setNotificationsError("The notification status could not be updated."); } }
  const markNotificationRead = (id: string) => setNotificationStatus(id, "read");
  async function newConversation() { const response = await averonApi.conversations.create(selectedWorkspaceId || null); setConversations((items) => [response.data, ...items]); setActiveConversationId(response.data.id); sessionStorage.setItem("averon:active-conversation", response.data.id); navigate("/chat"); }
  function selectConversation(item: EmmyConversation) { setActiveConversationId(item.id); sessionStorage.setItem("averon:active-conversation", item.id); setSelectedWorkspaceId(item.workspaceId ?? ""); if (item.workspaceId) sessionStorage.setItem("averon:selected-workspace", item.workspaceId); else sessionStorage.removeItem("averon:selected-workspace"); navigate("/chat"); }
  async function deleteConversation(item: EmmyConversation) { await averonApi.conversations.delete(item.id); setConversations((items) => items.filter((candidate) => candidate.id !== item.id)); if (activeConversationId === item.id) { setActiveConversationId(""); sessionStorage.removeItem("averon:active-conversation"); navigate("/chat"); } }
  if (!authReady) return <main className="app-loading"><span className="brand-orb"><Icon name="spark"/></span><strong>Emmy</strong><p>Securing your private workspace…</p></main>;
  const protectedView = (view: ReactNode) => <Protected user={user}><Shell session={session} selectedWorkspace={selectedWorkspace} unreadCount={unreadCount} conversations={conversations} activeConversationId={activeConversationId} onNewConversation={newConversation} onSelectConversation={selectConversation} onDeleteConversation={deleteConversation}>{view}</Shell></Protected>;
  const activeConversation = conversations.find((item) => item.id === activeConversationId);
  return <Routes><Route path="/login" element={<Login user={user}/>}/><Route path="/workspaces" element={protectedView(<Workspaces items={workspaces} loading={workspacesLoading} error={workspaceError} selectedId={selectedWorkspaceId} onSelect={selectWorkspace}/>)}/><Route path="/workspaces/:workspaceId/business-os" element={protectedView(<BusinessOsControlCenter/>)}/><Route path="/chat" element={protectedView(<PrivateEmmyChat workspace={selectedWorkspace} hasWorkspaces={workspaces.length > 0} conversation={activeConversation} onConversationCreated={(item) => { setConversations((items) => [item, ...items]); setActiveConversationId(item.id); sessionStorage.setItem("averon:active-conversation", item.id); }} onConversationUpdated={refreshConversations}/>)}/><Route path="/agents" element={protectedView(<AgentsView workspace={selectedWorkspace}/>)}/><Route path="/permissions" element={protectedView(<PermissionsView workspace={selectedWorkspace}/>)}/><Route path="/runs" element={protectedView(<RunsView workspace={selectedWorkspace}/>)}/><Route path="/tasks" element={protectedView(<TasksControlCenter workspace={selectedWorkspace}/>)}/><Route path="/automations" element={protectedView(<AutomationsControlCenter workspace={selectedWorkspace}/>)}/><Route path="/diagnostics" element={session?.isAdmin ? protectedView(<DiagnosticsView/>) : <Navigate to="/workspaces" replace/>}/><Route path="/notifications" element={protectedView(<NotificationsView items={notifications} workspaces={workspaces} loading={notificationsLoading} error={notificationsError} onRead={markNotificationRead}/>)}/><Route path="/settings" element={protectedView(<SettingsView session={session} apiOnline={apiOnline} selectedWorkspace={selectedWorkspace}/>)}/><Route path="*" element={<Navigate to={user ? "/workspaces" : "/login"} replace/>}/></Routes>;
}
